// Build a signed request body for the Convex overdue-check endpoint.

function sign(rawBody) {
  const secret = $env.LENDLOOP_WEBHOOK_SECRET;
  if (!secret) throw new Error('LENDLOOP_WEBHOOK_SECRET is not set in the n8n environment.');
  return require('crypto').createHmac('sha256', secret).update(rawBody, 'utf8').digest('hex');
}
function convexUrl(path) {
  const base = ($env.CONVEX_SITE_URL || '').replace(/\/$/, '');
  if (!base) throw new Error('CONVEX_SITE_URL is not set in the n8n environment (use the .convex.site URL).');
  return base + path;
}
const rawBody = JSON.stringify({ source: 'n8n-overdue-cron', requestedAt: new Date().toISOString() });
return [{ json: {
  rawBody,
  signature: 'sha256=' + sign(rawBody),
  url: convexUrl('/n8n/overdue-check'),
} }];

// One item per overdue loan. The eventId embeds the UTC date, which makes
// the write-back idempotent PER DAY: re-running the workflow the same day
// cannot send a duplicate log row, and Convex dedupes on this key.
const res = $input.first().json;
const today = new Date().toISOString().slice(0, 10);
const loans = Array.isArray(res.overdue) ? res.overdue : [];
return loans.map((loan) => ({ json: {
  ...loan,
  eventId: 'overdue:' + loan.borrowRequestId + ':' + today,
  toEmail: loan.borrowerEmail,
  subject: 'LendLoop reminder: "' + loan.toolName + '" is ' + loan.daysOverdue + ' day(s) overdue',
  text: [
    'Hi ' + loan.borrowerName + ',',
    '',
    'Just a friendly nudge: the "' + loan.toolName + '" you borrowed from ' + loan.ownerName +
      ' was due back on ' + loan.endDate + ' and is now ' + loan.daysOverdue + ' day(s) overdue.',
    'Please arrange the return as soon as you can.',
    '',
    '— LendLoop',
  ].join('\n'),
} }));

// Signed, idempotent write-back for one sent reminder.

function sign(rawBody) {
  const secret = $env.LENDLOOP_WEBHOOK_SECRET;
  if (!secret) throw new Error('LENDLOOP_WEBHOOK_SECRET is not set in the n8n environment.');
  return require('crypto').createHmac('sha256', secret).update(rawBody, 'utf8').digest('hex');
}
function convexUrl(path) {
  const base = ($env.CONVEX_SITE_URL || '').replace(/\/$/, '');
  if (!base) throw new Error('CONVEX_SITE_URL is not set in the n8n environment (use the .convex.site URL).');
  return base + path;
}
const item = $input.first().json;
const rawBody = JSON.stringify({
  eventId: item.eventId,
  borrowRequestId: item.borrowRequestId,
  daysOverdue: item.daysOverdue,
});
return [{ json: {
  rawBody,
  signature: 'sha256=' + sign(rawBody),
  url: convexUrl('/n8n/reminder-logged'),
} }];
